// === Tab: mySketch ===
// original:https://openprocessing.org/sketch/1852060

// 変更点
// fsでrgbにalphaを乗算
// drawにおけるgl.blen～～～を排除
// createBufferは1回で充分
// vertexColorsが不要なのでカット
// 背景を雲画像に変更
// マスクをストライプから雲画像に変更
// そんくらいですね
// あー、それと
// https://thebookofshaders.com/06/?lan=jp
// rgb2hsbを拝借
// これを使ってcolorをhsbに変換したうえで
// brightnessを使って透明度に掛け算
// これにより黒い部分を透明にして
// 明るい部分だけ見えるようにしました
// 以上です

// 色を赤系で揃えてみました。
// 余計なpush～popを外したうえで
// noStroke()を全体にかけました

// 雲背景用のシェーダーは
// 雲画像のデータをalpha値で用いるために
// rをalphaとして取得したうえで
// rgbに掛け算しています
// 水色から透明に向かうグラデーションと白背景で雲を表現しています
// せっかく透明度がきちんと計算されるようになったので
// それを生かすことにしました

// orbitControlを何とかしたいですね
// たとえばマウスを縦にドラッグした時
// 水平に回転した方が自然なのに
// 縦で回転するので気持ち悪い
// z軸正方向に向かって波打っているなら
// カスタムの方がいいと思う
// じきに準備しますね
// https://openprocessing.org/sketch/1402569

let gWidth = 1112;
let gHeight = 834;
let scl = 60;

let cloudImg;

let eyeVector, toCenterVector, sideVector, upVector;
// カメラ変数
let posR = 480;
let posTheta = Math.PI/32;
let posPhi = 0;

let _gl, gl;

let useShader;

let vs = `
precision mediump float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;
uniform float time;

varying vec2 vTexCoord;
varying vec4 vPosition;

vec4 mod289(vec4 x) {
	return x - floor(x * (1.0 / 289.0)) * 289.0; 
}

float mod289(float x) {
	return x - floor(x * (1.0 / 289.0)) * 289.0; 
}

vec4 permute(vec4 x) {
	return mod289(((x*34.0)+1.0)*x);
}

float permute(float x) {
	return mod289(((x*34.0)+1.0)*x);
}

vec4 taylorInvSqrt(vec4 r)
{
	return 1.79284291400159 - 0.85373472095314 * r;
}

float taylorInvSqrt(float r)
{
	return 1.79284291400159 - 0.85373472095314 * r;
}

vec4 grad4(float j, vec4 ip)
{
	const vec4 ones = vec4(1.0, 1.0, 1.0, -1.0);
	vec4 p,s;

	p.xyz = floor( fract (vec3(j) * ip.xyz) * 7.0) * ip.z - 1.0;
	p.w = 1.5 - dot(abs(p.xyz), ones.xyz);
	s = vec4(lessThan(p, vec4(0.0)));
	p.xyz = p.xyz + (s.xyz*2.0 - 1.0) * s.www;

	return p;
}

// (sqrt(5) - 1)/4 = F4, used once below
#define F4 0.309016994374947451

float snoise(vec4 v)
{
	const vec4  C = vec4( 0.138196601125011,  // (5 - sqrt(5))/20  G4
							0.276393202250021,  // 2 * G4
							0.414589803375032,  // 3 * G4
							-0.447213595499958); // -1 + 4 * G4

	// First corner
	vec4 i  = floor(v + dot(v, vec4(F4)) );
	vec4 x0 = v -   i + dot(i, C.xxxx);

	// Other corners

	// Rank sorting originally contributed by Bill Licea-Kane, AMD (formerly ATI)
	vec4 i0;
	vec3 isX = step( x0.yzw, x0.xxx );
	vec3 isYZ = step( x0.zww, x0.yyz );
	//  i0.x = dot( isX, vec3( 1.0 ) );
	i0.x = isX.x + isX.y + isX.z;
	i0.yzw = 1.0 - isX;
	//  i0.y += dot( isYZ.xy, vec2( 1.0 ) );
	i0.y += isYZ.x + isYZ.y;
	i0.zw += 1.0 - isYZ.xy;
	i0.z += isYZ.z;
	i0.w += 1.0 - isYZ.z;

	// i0 now contains the unique values 0,1,2,3 in each channel
	vec4 i3 = clamp( i0, 0.0, 1.0 );
	vec4 i2 = clamp( i0-1.0, 0.0, 1.0 );
	vec4 i1 = clamp( i0-2.0, 0.0, 1.0 );

	//  x0 = x0 - 0.0 + 0.0 * C.xxxx
	//  x1 = x0 - i1  + 1.0 * C.xxxx
	//  x2 = x0 - i2  + 2.0 * C.xxxx
	//  x3 = x0 - i3  + 3.0 * C.xxxx
	//  x4 = x0 - 1.0 + 4.0 * C.xxxx
	vec4 x1 = x0 - i1 + C.xxxx;
	vec4 x2 = x0 - i2 + C.yyyy;
	vec4 x3 = x0 - i3 + C.zzzz;
	vec4 x4 = x0 + C.wwww;

	// Permutations
	i = mod289(i);
	float j0 = permute( permute( permute( permute(i.w) + i.z) + i.y) + i.x);
	vec4 j1 = permute( permute( permute( permute (
				i.w + vec4(i1.w, i2.w, i3.w, 1.0 ))
				+ i.z + vec4(i1.z, i2.z, i3.z, 1.0 ))
				+ i.y + vec4(i1.y, i2.y, i3.y, 1.0 ))
				+ i.x + vec4(i1.x, i2.x, i3.x, 1.0 ));

	// Gradients: 7x7x6 points over a cube, mapped onto a 4-cross polytope
	// 7*7*6 = 294, which is close to the ring size 17*17 = 289.
	vec4 ip = vec4(1.0/294.0, 1.0/49.0, 1.0/7.0, 0.0) ;

	vec4 p0 = grad4(j0,   ip);
	vec4 p1 = grad4(j1.x, ip);
	vec4 p2 = grad4(j1.y, ip);
	vec4 p3 = grad4(j1.z, ip);
	vec4 p4 = grad4(j1.w, ip);

	// Normalise gradients
	vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
	p0 *= norm.x;
	p1 *= norm.y;
	p2 *= norm.z;
	p3 *= norm.w;
	p4 *= taylorInvSqrt(dot(p4,p4));

	// Mix contributions from the five corners
	vec3 m0 = max(0.6 - vec3(dot(x0,x0), dot(x1,x1), dot(x2,x2)), 0.0);
	vec2 m1 = max(0.6 - vec2(dot(x3,x3), dot(x4,x4)            ), 0.0);
	m0 = m0 * m0;
	m1 = m1 * m1;
	return 49.0 * ( dot(m0*m0, vec3( dot( p0, x0 ), dot( p1, x1 ), dot( p2, x2 )))
					+ dot(m1*m1, vec2( dot( p3, x3 ), dot( p4, x4 ) ) ) ) ;

}

void main() { 
    vec3 uPosition = aPosition + vec3(0.0, 0.0, snoise(vec4(aPosition * 0.005 + vec3(0.0, -time * 0.2, 0.0), time * 0.0)) * 100.0);
    vec4 positionVec4 = vec4(uPosition, 1.0);
	vPosition = positionVec4;

    gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;//positionVec4;
    vTexCoord = aTexCoord;
}
`;

let fs = `
#ifdef GL_ES
precision mediump float;
#endif

varying vec2 vTexCoord;
varying vec4 vPosition;

uniform sampler2D tex;
uniform float time;
uniform vec2 planeResolution;
uniform sampler2D uTex;

vec3 color;

#define COLOR_N vec3(0.6, 0.44, 0.35)
#define COLOR_T vec3(0.816, 0.816, 0.313)
#define COLOR_M vec3(0.745, 0.543, 0.318)
#define COLOR_K vec3(0.765, 0.504, 0.475)
#define COLOR_H vec3(1.0, 0.776, 0.224)
#define COLOR_S vec3(0.997, 0.706, 0.312)

float random2d(vec2 p){
    return fract(sin(dot(p, vec2(12.64524, 94.1241))) * 241222.21414);
}

float sdRect(vec2 p, vec2 s){
    vec2 q = abs(p) - s;
    return max(q.x, q.y);
}

vec3 lattice(vec2 uv, float s){
    // uv += vec2(time*0.02);
    uv *= s;
    vec3 col = vec3(0.0);
    vec2 fPos = fract(uv) - 0.5;
    vec2 iPos = floor(uv);
    vec3 sColor = COLOR_N;
    float rand = random2d(iPos);
    if(0.1 < rand && rand <= 0.3){
        sColor = COLOR_T;
    }else if(0.3 < rand && rand <= 0.5){
        sColor = COLOR_M;
    }else if(0.5 < rand && rand <= 0.7){
        sColor = COLOR_K;
    }else if(0.7 < rand && rand <= 0.9){
        sColor = COLOR_H;
    }

    float rectScale = random2d(iPos + vec2(222.3141, 1241.142));
    float rectScale2 = random2d(iPos * vec2(222.3141, 1241.142));
    float rectLen = ((sin(rectScale*222.2+time*0.2)+1.0)*0.125) + ((cos(rectScale2*22.2+time*0.4)+1.0)*0.25);
    col += smoothstep(0.1, -0.1, sdRect(fPos, vec2(rectLen))) * sColor;

    return col;
}

vec3 rgb2hsb( in vec3 c ){
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz),
                 vec4(c.gb, K.xy),
                 step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r),
                 vec4(c.r, p.yzx),
                 step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)),
                d / (q.x + e),
                q.x);
}

void main() {
	vec2 planeUv = vec2(vPosition.x / planeResolution.x, vPosition.y / planeResolution.y); // 0 ~ 1
	vec2 planeUv2 = (planeUv - 0.5) * 2.0;  // 0 ~ 1
	color = lattice(planeUv2, 4.0);
	//float a = sin(vPosition.y / 4.0 + time * 2.0) * 2.0;
	float a = texture2D(uTex, fract(vTexCoord + time * vec2(0.02, 0.01))).r;
	a *= rgb2hsb(color).z;
	gl_FragColor = vec4(color*a, a);
	// gl_FragColor = vec4(color, sin(vPosition.y/4.0 + time));
}
`;

let bgShader;

const vsBG = `
attribute vec3 aPosition;
varying vec2 vUv;
void main(){
  vUv = aPosition.xy * 0.5 + 0.5;
	vUv.y = 1.0 - vUv.y;
	gl_Position = vec4(aPosition, 1.0);
}
`;

const fsBG = `
precision mediump float;
uniform sampler2D uTex;
uniform float uTime;
varying vec2 vUv;
void main(){
  float alpha = texture2D(uTex, fract(vUv + uTime * vec2(-0.01, 0.02))).r;
	vec3 col = vec3(0.2, 0.6, 1.0);
	gl_FragColor = vec4(col * alpha, alpha);
}
`;

function preload(){
	cloudImg = loadImage("https://inaridarkfox4231.github.io/assets/texture/cloud.png");
}

function setup() {
	// createCanvas(windowWidth, windowHeight);
	// createCanvas(800, 800, WEBGL);
	createCanvas(gWidth, gHeight, WEBGL);
	noStroke();

	useShader = createShader(vs, fs);
	bgShader = createShader(vsBG, fsBG);
	_gl = this._renderer;
	gl = _gl.GL;
	terrainGeometry = createTerrain(800, 800, scl, scl);
	terrainGeometry.computeNormals();
	_gl.createBuffers("terrainGeometry", terrainGeometry);

  eyeVector = createVector();
  toCenterVector = createVector();
  sideVector = createVector();
  upVector = createVector();
}

function draw() {
	background(255);

	gl.disable(gl.DEPTH_TEST);
	push();
	camera(0, 0, height*0.5*sqrt(3), 0, 0, 0, 0, 1, 0);
	shader(bgShader);
	bgShader.setUniform("uTex", cloudImg);
	bgShader.setUniform("uTime", frameCount*0.1);
	quad(-1, -1, 1, -1, 1, 1, -1, 1);
	pop();
	gl.enable(gl.DEPTH_TEST);

	shader(useShader);
	useShader.setUniform("time", frameCount*0.1);
	useShader.setUniform("planeResolution", [gWidth, gHeight]);
	useShader.setUniform("uTex", cloudImg);

	//orbitControl(2, 1, 0.05);
  // set side & up Vectors.
  moveCamera()
  eyeVector.set(posR*cos(posTheta)*cos(posPhi),
                posR*cos(posTheta)*sin(posPhi),
                posR*sin(posTheta));
  camera(eyeVector.x, eyeVector.y, eyeVector.z, 0, 0, 0, 0, 0, -1);
  const m = _gl.uMVMatrix.copy().mat4;
  toCenterVector.set(-m[2], -m[6], -m[10]);
  sideVector.set(m[0], m[4], m[8]);
  upVector.set(m[1], m[5], m[9]);

	_gl.drawBuffersScaled("terrainGeometry", 1, 1, 1);

}

function createTerrain(w = 400, h = 400, detailX = 1, detailY = 1)
{
	let terrainGeom = new p5.Geometry(
		detailX, detailY,
		function createGeometry() {
			let u;
			let v;
			let p;

			for (let y = 0; y <= detailY; y++) {
				v = y / detailX;
				for (let x = 0; x <= detailX; x++) {
					u = x / detailX;
					p = new p5.Vector(u - 0.5, v - 0.5, 0.0);
					let pos = new p5.Vector(p.x * w, p.y * h);
					this.vertices.push(pos);
					this.uvs.push(u, v);
				}
			}

			this.computeFaces();
			this.computeNormals();
			this._makeTriangleEdges();
			this._edgesToVertices();

			this.gid = 'terrain|${w}|${h}|${detailX}|${detailY}|';
		}
	);

	return terrainGeom;
}

function moveCamera(){
  if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))){
    if(mouseButton == LEFT){
      posPhi += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))*0.01;
      posTheta = constrain(posTheta + ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))*0.01, -PI/2+0.01, PI/2-0.01);
    }
  }
}

function mouseWheel(){
  posR = constrain(posR + event.delta*0.5, 240, 1200);
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

